using System.Diagnostics;
using System.IO;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using Microsoft.Win32;
using Redshift.Services;
namespace Redshift;
namespace Redshift;
public partial class MainWindow:Window {
 readonly BluestacksService bs=new(); SettingsStore settings=new(); TextBlock status=new(); AndroidManager AndroidApi=>new(new AdbClient(settings.AdbPath)); string? selectedDevice;
 public MainWindow(){InitializeComponent();Loaded+=async(_,_)=>{settings=await SettingsStore.LoadAsync();Dashboard(null,null);};}
 void Dashboard(object? s,RoutedEventArgs? e){Page("Dashboard","Your gaming environment at a glance.");Cards.Children.Clear();foreach(var x in new[]{("BLUESTACKS",bs.Locate(settings.BlueStacksPath)!=null?"DETECTED":"NOT FOUND"),("ADB",string.IsNullOrWhiteSpace(settings.AdbPath)?"SYSTEM PATH":"CUSTOM PATH"),("PROFILES",settings.Profiles.Count.ToString()),("MODE","REDSHIFT CRIMSON")})Cards.Children.Add(Card(x.Item1,x.Item2));PageContent.Children.Clear();Add("Launch BlueStacks",(_,_)=>Launch());Add("Stop BlueStacks",(_,_)=>Stop());Add("Restart BlueStacks",(_,_)=>{Stop();Launch();});Add("Refresh diagnostics",(_,_)=>Diagnostics(null,null));}
 void Page(string t,string sub){PageTitle.Text=t;Subtitle.Text=sub;}
 TextBlock Card(string a,string b)=>new(){Text=a+"\n"+b,FontSize=16,Margin=new Thickness(0,0,14,14),Padding=new Thickness(18),Background=new SolidColorBrush(Color.FromRgb(32,35,48)),Width=190};
 void Add(string text,RoutedEventHandler click){var b=new Button{Content=text};b.Click+=click;PageContent.Children.Add(b);}
 void Standoff(object? s,RoutedEventArgs? e){Page("Standoff 2","Select a device before applying profiles.");PageContent.Children.Clear();Add("Select connected device",async(_,_)=>{var ds=await AndroidApi.ListDevicesAsync();if(ds.Count==0){status.Text="No ready ADB devices.";return;}var d=new DevicePicker(ds){Owner=this};if(d.ShowDialog()==true){selectedDevice=d.SelectedDevice;status.Text=$"Selected {selectedDevice}";}});Add("Restore saved display",async(_,_)=>{if(selectedDevice==null||!settings.PackageProfiles.TryGetValue("display:"+selectedDevice,out var saved)){status.Text="Select device or saved display state missing.";return;}var v=saved.Split('|');if(v.Length!=2){status.Text="Saved display data invalid.";return;}var api=new AdbClient(settings.AdbPath);var a=await api.ExecuteAsync($"-s {selectedDevice} shell wm size {v[0]}");var b=await api.ExecuteAsync($"-s {selectedDevice} shell wm density {v[1]}");status.Text=$"Size {(a.Success?"OK":a.Output)}\nDPI {(b.Success?"OK":b.Output)}";});foreach(var p in settings.Profiles)Add($"Apply {p.Name} · {p.Width}×{p.Height}",async(_,_)=>{if(selectedDevice==null){status.Text="Select a device first.";return;}var check=BluestacksService.ValidateProfile(p);if(!check.StartsWith("supported")){status.Text=check;return;}var api=new AdbClient(settings.AdbPath);var key="display:"+selectedDevice;if(!settings.PackageProfiles.ContainsKey(key)){var old=await new AutoProfileService(api).ReadDisplayAsync(selectedDevice);if(!old.Success){status.Text="Could not read prior display; not applied. "+old.Error;return;}settings.PackageProfiles[key]=$"{old.Size}|{old.Density}";await settings.SaveAsync();}var dpi=await api.ExecuteAsync($"-s {selectedDevice} shell wm density {p.Dpi}");if(!dpi.Success){status.Text=dpi.Output;return;}var size=await api.ExecuteAsync($"-s {selectedDevice} shell wm size {p.Width}x{p.Height}");status.Text=$"DPI {(dpi.Success?"OK":dpi.Output)}; size {(size.Success?"OK":size.Output)}";});Add("Reset display defaults",async(_,_)=>{if(selectedDevice==null){status.Text="Select device first.";return;}var api=new AdbClient(settings.AdbPath);await api.ExecuteAsync($"-s {selectedDevice} shell wm size reset");await api.ExecuteAsync($"-s {selectedDevice} shell wm density reset");status.Text="Reset requested.";});Add("Validate profiles",(_,_)=>status.Text=string.Join("\n",settings.Profiles.Select(p=>$"{p.Name}: {BluestacksService.ValidateProfile(p)}")));PageContent.Children.Add(status);}
 async void Performance(object? s,RoutedEventArgs? e){Page("Performance","Host and emulator metrics.");PageContent.Children.Clear();Add("Refresh metrics",async(_,_)=>{var data=await new PerformanceMonitor().SampleBlueStacksAsync();status.Text=data.Count==0?"BlueStacks is not running.":string.Join("\n",data.Select(x=>$"PID {x.ProcessId}: CPU {x.CpuPercent}% · RAM {x.RamMb} MB"))+"\nFPS unavailable without emulator telemetry.";});Add("Smart Booster analysis",(_,_)=>{var r=new SmartBooster().Analyze();status.Text=$"Suggested: {r.Mode}\nAvailable RAM: {r.AvailableRamMb} MB\n"+string.Join("\n",r.Recommendations);});PageContent.Children.Add(status);}
 void Resolution(object? s,RoutedEventArgs? e){Page("Resolution Engine","Android resolution and window size are controlled separately.");PageContent.Children.Clear();Add("Find BlueStacks windows",(_,_)=>{var w=new WindowScaler().FindBlueStacksWindows();status.Text=w.Count==0?"No visible window found.":string.Join("\n",w.Select(x=>$"PID {x.ProcessId} {x.Width}×{x.Height}"));});Add("Resize window to 4:3",(_,_)=>{var w=new WindowScaler().FindBlueStacksWindows().FirstOrDefault();status.Text=w==null?"No visible window found.":new WindowScaler().ApplyStretched43(w,Math.Max(480,w.Height))?"Window resized; Android resolution unchanged.":"Resize failed.";});Add("Select Android device",async(_,_)=>{var ds=await AndroidApi.ListDevicesAsync();if(ds.Count==0){status.Text="No ready device.";return;}var d=new DevicePicker(ds){Owner=this};if(d.ShowDialog()==true)selectedDevice=d.SelectedDevice;});Add("Reset Android display",async(_,_)=>{if(selectedDevice==null){status.Text="Select device first.";return;}var api=new AdbClient(settings.AdbPath);await api.ExecuteAsync($"-s {selectedDevice} shell wm size reset");await api.ExecuteAsync($"-s {selectedDevice} shell wm density reset");status.Text="Android display reset requested.";});PageContent.Children.Add(status);}
 async void Android(object? s,RoutedEventArgs? e){Page("Android Manager","Manage the selected ADB device.");PageContent.Children.Clear();Add("Select device",async(_,_)=>{var ds=await AndroidApi.ListDevicesAsync();if(ds.Count==0){status.Text="No ready devices.";return;}var d=new DevicePicker(ds){Owner=this};if(d.ShowDialog()==true)selectedDevice=d.SelectedDevice;});Add("List packages",async(_,_)=>{var r=await AndroidApi.ListPackagesAsync();status.Text=r.Output;});Add("Install APK",async(_,_)=>{var d=new OpenFileDialog{Filter="APK (*.apk)|*.apk"};if(d.ShowDialog()==true)status.Text=(await AndroidApi.InstallApkAsync(d.FileName)).Output;});Add("Uninstall package",async(_,_)=>{var d=new TextInputDialog("Package name"){Owner=this};if(d.ShowDialog()==true)status.Text=(await AndroidApi.UninstallAsync(d.Value)).Output;});Add("Push file to Downloads",async(_,_)=>{var d=new OpenFileDialog();if(d.ShowDialog()==true)status.Text=(await AndroidApi.PushFileAsync(d.FileName,"/sdcard/Download/"+Path.GetFileName(d.FileName))).Output;});Add("Restart Android",async(_,_)=>status.Text=(await AndroidApi.RestartAndroidAsync()).Output);PageContent.Children.Add(status);}
 void Diagnostics(object? s,RoutedEventArgs? e){Page("Diagnostics","Environment report");PageContent.Children.Clear();string report="";Add("Run checks",async(_,_)=>{var r=await bs.RunAdbAsync("devices",settings.AdbPath);report=new DiagnosticsService().CreateReport(bs.Locate(settings.BlueStacksPath),r.output,r.ok);status.Text=report;});Add("Export report",async(_,_)=>status.Text=string.IsNullOrEmpty(report)?"Run checks first.":await new DiagnosticsService().ExportAsync(report,Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Desktop),"REDSHIFT-Reports")));PageContent.Children.Add(status);}
 void Settings(object? s,RoutedEventArgs? e){Page("Settings","BlueStacks and ADB configuration");PageContent.Children.Clear();var b=new TextBox{Text=settings.BlueStacksPath??""};var a=new TextBox{Text=settings.AdbPath??""};PageContent.Children.Add(b);PageContent.Children.Add(a);Add("Save paths",async(_,_)=>{settings.BlueStacksPath=string.IsNullOrWhiteSpace(b.Text)?null:b.Text.Trim();settings.AdbPath=string.IsNullOrWhiteSpace(a.Text)?null:a.Text.Trim();await settings.SaveAsync();status.Text="Saved.";});Add("Export profiles",async(_,_)=>{var p=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Desktop),"redshift-profiles.json");await settings.ExportProfilesAsync(p);status.Text=p;});Add("Import profiles",async(_,_)=>{var d=new OpenFileDialog{Filter="JSON (*.json)|*.json"};if(d.ShowDialog()==true)status.Text=(await settings.ImportProfilesAsync(d.FileName)).Message;});Add("Backup settings",async(_,_)=>status.Text=await settings.BackupAsync());Add("Restore backup",async(_,_)=>{var d=new OpenFileDialog{Filter="JSON (*.json)|*.json"};if(d.ShowDialog()==true){await settings.RestoreAsync(d.FileName);status.Text="Restored.";}});PageContent.Children.Add(status);}
 void Keymapping(object? s,RoutedEventArgs? e){Page("Keymapping Studio","Bindings are stored locally; import into BlueStacks separately.");PageContent.Children.Clear();var path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"REDSHIFT","standoff2-keymap.json");var p=new KeymappingProfile();var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition());grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(150)});for(var i=0;i<p.Bindings.Count;i++){grid.RowDefinitions.Add(new RowDefinition());var label=new TextBlock{Text=p.Bindings[i].Action};var key=new TextBox{Text=p.Bindings[i].Key};Grid.SetRow(label,i);Grid.SetRow(key,i);Grid.SetColumn(key,1);grid.Children.Add(label);grid.Children.Add(key);}PageContent.Children.Add(grid);Add("Save keymap",async(_,_)=>{for(var i=0;i<p.Bindings.Count;i++)p.Bindings[i]=p.Bindings[i] with{Key=((TextBox)grid.Children.Cast<UIElement>().First(x=>Grid.GetRow(x)==i&&Grid.GetColumn(x)==1)).Text};if(!KeymappingStore.Validate(p,out var m)){status.Text=m;return;}await new KeymappingStore().SaveAsync(p,path);status.Text="Saved.";});PageContent.Children.Add(status);}
 void Overlay(object? s,RoutedEventArgs? e){Page("Gaming Overlay","Session timer and emulator RAM.");PageContent.Children.Clear();var opacity=new Slider{Minimum=.2,Maximum=1,Value=settings.Overlay.Opacity};var scale=new Slider{Minimum=.6,Maximum=2,Value=settings.Overlay.Scale};PageContent.Children.Add(opacity);PageContent.Children.Add(scale);Add("Save overlay settings",async(_,_)=>{settings.Overlay=settings.Overlay with{Opacity=opacity.Value,Scale=scale.Value};await settings.SaveAsync();status.Text="Saved.";});Add("Show overlay",(_,_)=>{var w=new OverlayWindow();w.Configure(settings.Overlay with{Opacity=opacity.Value,Scale=scale.Value});w.Show();});PageContent.Children.Add(status);}
 async void Gaming(object? s,RoutedEventArgs? e){Page("Gaming Center","Search and launch installed Android packages.");PageContent.Children.Clear();var search=new TextBox{Height=32};PageContent.Children.Add(search);var list=new StackPanel();PageContent.Children.Add(list);var api=new GameLibrary(new AdbClient(settings.AdbPath));IReadOnlyList<InstalledGame> games=[];void Render(){list.Children.Clear();foreach(var g in games.Where(x=>x.PackageName.Contains(search.Text,StringComparison.OrdinalIgnoreCase)).Take(100)){var row=new StackPanel{Orientation=Orientation.Horizontal};var fav=new Button{Content=settings.FavoritePackages.Contains(g.PackageName)?"★":"☆",Width=48};fav.Click+=async(_,_)=>{if(!settings.FavoritePackages.Remove(g.PackageName))settings.FavoritePackages.Add(g.PackageName);await settings.SaveAsync();Render();};row.Children.Add(fav);var run=new Button{Content=g.PackageName};run.Click+=async(_,_)=>status.Text=(await api.LaunchAsync(g.PackageName)).Output;row.Children.Add(run);list.Children.Add(row);}}search.TextChanged+=(_,_)=>Render();Add("Refresh apps",async(_,_)=>{games=await api.DiscoverAsync();status.Text=$"Found {games.Count}.";Render();});PageContent.Children.Add(status);}
 void Instances(object? s,RoutedEventArgs? e){Page("Multi Instance","Running BlueStacks processes.");PageContent.Children.Clear();Add("Refresh",(_,_)=>{var rows=new MultiInstanceManager().GetRunning();status.Text=rows.Count==0?"No emulator process.":string.Join("\n",rows.Select(x=>$"PID {x.ProcessId}"));});Add("Launch BlueStacks",(_,_)=>Launch());PageContent.Children.Add(status);}
 async void Network(object? s,RoutedEventArgs? e){Page("Network Monitor","Ping sample");PageContent.Children.Clear();Add("Ping",async(_,_)=>{var n=await new NetworkMonitor().PingAsync();status.Text=n.Reachable?$"{n.Host}: {n.LatencyMs}ms":n.Error;});PageContent.Children.Add(status);}
 void Launch(){var path=bs.Locate(settings.BlueStacksPath);if(path==null){status.Text="BlueStacks not found; configure path in Settings.";return;}try{Process.Start(new ProcessStartInfo(path){UseShellExecute=true});status.Text="Launch requested.";}catch(Exception ex){status.Text=ex.Message;}}
 void Stop(){foreach(var p in Process.GetProcessesByName("HD-Player"))try{p.CloseMainWindow();}catch{} status.Text="Stop requested.";}
}
